{
  "judgments": [
    {
      "proposal_id": "P0000",
      "quotes": [
        "if the applicant has a name with multiple parts, you must determine how the name will appear:"
      ],
      "rationale": "The proposed condition targets C0017 along with C0018, C0019, and C0020. However, C0017 already incorporates this exact conditional clause directly into its baseline definition and scope ('if the applicant has a name with multiple parts, you must determine how the name will appear:'). Conditioning C0017 on an external copy of its own antecedent is inappropriate and fails to establish a valid target baseline. Furthermore, C0018, C0019, and C0020 already fully incorporate this multi-part name condition within their scope definitions, so the addition does not fix a real defect or support every target.",
      "verdict": "unsupported"
    },
    {
      "proposal_id": "P0001",
      "quotes": [
        "If you receive applications from several family members, you should space the last names consistently, unless a family member expresses a clear preference for a different spacing."
      ],
      "rationale": "The proposal legitimately converts an existing prose caveat in C0021 into an explicit companion exception edge. It correctly targets the baseline recommendation in C0021, preserves the non-mandatory modal force of an exception relaxing a recommendation without asserting absence of a legal duty, and accurately matches the text and offsets in the source.",
      "verdict": "supported"
    }
  ]
}
